// Mirrors southpark-demo/src/scoring/lead-scoring.ts
const config = {
  serviceAreas: ($env.SERVICE_AREAS || 'Abilene,Texas,DFW').split(',').map(s => s.trim()),
  acceptedServices: ($env.ACCEPTED_SERVICES || 'Commercial Renovation,Tenant Improvement,Restaurant Build-Out').split(',').map(s => s.trim()),
  minimumBudget: Number($env.MINIMUM_BUDGET || 10000),
  businessName: $env.BUSINESS_NAME || 'Southpark Construction',
};

const body = $input.first().json.body ?? $input.first().json;
const structured = body.message?.analysis?.structuredData ?? body.analysis?.structuredData ?? {};
const call = body.message?.call ?? body.call ?? {};

const report = {
  ...structured,
  call_summary: structured.call_summary || body.message?.analysis?.summary || '',
  call_id: structured.call_id || call.id || '',
  recording_url: structured.recording_url || call.recordingUrl || '',
  transcript_url: structured.transcript_url || call.transcriptUrl || '',
  call_started_at: structured.call_started_at || call.startedAt || '',
};

function parseBudget(v) {
  if (!v) return null;
  const m = String(v).replace(/,/g,'').match(/\$?\s*(\d+(?:\.\d+)?)\s*(k|m)?/i);
  if (!m) return null;
  let n = parseFloat(m[1]);
  if ((m[2]||'').toLowerCase()==='k') n *= 1000;
  if ((m[2]||'').toLowerCase()==='m') n *= 1000000;
  return n;
}

function e164(p) {
  if (!p) return undefined;
  const d = String(p).replace(/\D/g,'');
  if (d.length===10) return '+1'+d;
  if (d.length===11 && d.startsWith('1')) return '+'+d;
  return undefined;
}

const hay = [report.scope_description, report.notes, report.call_summary, report.urgency].join(' ').toLowerCase();
const emergency = ['fire','injury','gas smell','flooding','electrical hazard','911'].some(k => hay.includes(k)) || report.urgency==='Emergency';

let lead_status = 'Needs Review';
if (emergency) lead_status = 'Urgent';
else if (report.caller_type === 'New Lead') {
  const loc = [report.project_location, report.city, report.zip_code].join(' ').toLowerCase();
  const inArea = config.serviceAreas.some(a => loc.includes(a.toLowerCase())) || /texas|\btx\b|abilene|dallas|dfw/.test(loc);
  const budget = parseBudget(report.budget_range);
  const commercial = /commercial|restaurant|retail|office|tenant/.test((report.property_type||'') + (report.project_type||''));
  const phone = e164(report.phone);
  if (!inArea && /\b(ca|ny|fl)\b/.test(loc)) lead_status = 'Not a Fit';
  else if (budget != null && budget < config.minimumBudget && !commercial) lead_status = 'Not a Fit';
  else if (phone) lead_status = 'Qualified';
}

return [{ json: { report, lead_status, phone_e164: e164(report.phone), config } }];

